+	if (!turn.scored) return { status: "unscored", recommendedForSft: false, scored: false, signals: turn.signals };
+	const status: TrainingQualityStatus = turn.reward >= KTO_GOOD_THRESHOLD
+		? "accepted"
+		: turn.reward <= 0.35
+			? "rejected"
+			: "review";
+	return {
